#include <ctype.h>

const char *version_str = "LuaJIT 2.1.1772570160 -- Copyright (C) 2005-2026 Mike Pall. https://luajit.org/";

void print_usage(const char *prog) {
    printf("usage: %s [options]... [script [args]...].\n", prog);
    printf("Available options are:\n");
    printf("  -e chunk  Execute string 'chunk'.\n");
    printf("  -l name   Require library 'name'.\n");
    printf("  -b ...    Save or list bytecode.\n");
    printf("  -j cmd    Perform LuaJIT control command.\n");
    printf("  -O[opt]   Control LuaJIT optimizations.\n");
    printf("  -i        Enter interactive mode after executing 'script'.\n");
    printf("  -v        Show version information.\n");
    printf("  -E        Ignore environment variables.\n");
    printf("  --        Stop handling options.\n");
    printf("  -         Execute stdin and stop handling options.\n");
}

// Trim leading/trailing whitespace
char *trim(char *s) {
    if (!s) return s;
    while(isspace((unsigned char)*s)) s++;
    if (*s == 0) return s;
    char *end = s + strlen(s) - 1;
    while(end > s && isspace((unsigned char)*end)) end--;
    *(end+1) = '\0';
    return s;
}

// Very small evaluator: supports print(...) with string or numeric literals, separated by commas
void eval_chunk(const char *chunk) {
    if (!chunk) return;
    const char *p = strstr(chunk, "print");
    if (!p) return; // nothing to do for unknown chunks
    const char *open = strchr(p, '(');
    if (!open) return;
    const char *close = strrchr(open, ')');
    if (!close) close = chunk + strlen(chunk);
    // extract inside
    size_t len = close - open - 1;
    char *inside = (char*)malloc(len + 1);
    if (!inside) return;
    memcpy(inside, open + 1, len);
    inside[len] = '\0';
    // parse comma-separated args
    char *s = inside;
    int first = 1;
    while (*s) {
        // skip spaces
        while (isspace((unsigned char)*s)) s++;
        if (*s == '\0') break;
        char *argstart = s;
        char quote = 0;
        if (*s == '"' || *s == '\'') {
            quote = *s;
            s++;
            char buf[1024];
            int bi = 0;
            while (*s && *s != quote) {
                if (*s == '\\' && *(s+1)) { s++; buf[bi++] = *s++; }
                else buf[bi++] = *s++;
                if (bi >= (int)sizeof(buf)-1) break;
            }
            buf[bi] = '\0';
            if (!first) printf("\t");
            printf("%s", buf);
            if (*s == quote) s++;
        } else {
            // parse until comma
            char buf[1024];
            int bi = 0;
            while (*s && *s != ',') {
                buf[bi++] = *s++; if (bi >= (int)sizeof(buf)-1) break;
            }
            buf[bi] = '\0';
            char *t = trim(buf);
            if (t && *t) {
                if (!first) printf("\t");
                printf("%s", t);
            }
        }
        // skip until comma
        while (*s && *s != ',') s++;
        if (*s == ',') s++;
        first = 0;
    }
    free(inside);
    printf("\n");
}

void run_interactive() {
    // Simple REPL: read lines and eval
    char line[4096];
    while (1) {
        if (!isatty(fileno(stdin))) break; // don't block if not tty
        printf("\n> ");
        if (!fgets(line, sizeof(line), stdin)) break;
        // trim newline
        size_t L = strlen(line);
        if (L && line[L-1] == '\n') line[L-1] = '\0';
        if (strcmp(line, "exit") == 0 || strcmp(line, "quit") == 0) break;
        eval_chunk(line);
    }
}

int main(int argc, char **argv) {
    int interactive = 0;
    int ignore_env = 0;
    int did_something = 0;

    if (argc > 1) {
        // quick check for --help first
        for (int i = 1; i < argc; i++) {
            if (strcmp(argv[i], "--help") == 0) {
                print_usage(argv[0]);
                return 0;
            }
        }
    }

    for (int i = 1; i < argc; ++i) {
        char *arg = argv[i];
        if (strcmp(arg, "--") == 0) {
            // stop option processing; next arg is script
            if (i+1 < argc) {
                // execute script file
                const char *fname = argv[i+1];
                FILE *f = fopen(fname, "r");
                if (f) {
                    fseek(f, 0, SEEK_END);
                    long sz = ftell(f);
                    fseek(f, 0, SEEK_SET);
                    char *buf = malloc(sz+1);
                    if (buf) {
                        fread(buf,1,sz,f);
                        buf[sz] = '\0';
                        eval_chunk(buf);
                        free(buf);
                    }
                    fclose(f);
                }
                did_something = 1;
                break;
            }
        }
        if (strcmp(arg, "-v") == 0) {
            printf("%s\n", version_str);
            return 0;
        } else if (strcmp(arg, "-e") == 0) {
            if (i+1 < argc) {
                eval_chunk(argv[i+1]);
                did_something = 1;
                i++;
                continue;
            }
        } else if (strcmp(arg, "-l") == 0) {
            if (i+1 < argc) { i++; continue; }
        } else if (strcmp(arg, "-i") == 0) {
            interactive = 1; continue;
        } else if (strcmp(arg, "-E") == 0) {
            ignore_env = 1; continue;
        } else if (strcmp(arg, "-") == 0) {
            // read from stdin
            // read all
            char *buf = NULL;
            size_t cap = 0;
            size_t len = 0;
            char tmp[4096];
            size_t r;
            while ((r = fread(tmp,1,sizeof(tmp),stdin)) > 0) {
                if (len + r + 1 > cap) {
                    cap = (len + r + 1) * 2;
                    buf = realloc(buf, cap);
                }
                memcpy(buf + len, tmp, r);
                len += r;
            }
            if (buf) {
                buf[len] = '\0';
                eval_chunk(buf);
                free(buf);
                did_something = 1;
            }
            break;
        } else if (arg[0] == '-') {
            // other flags: -b, -j, -O
            // treat as no-op
            continue;
        } else {
            // script file
            const char *fname = arg;
            FILE *f = fopen(fname, "r");
            if (f) {
                fseek(f, 0, SEEK_END);
                long sz = ftell(f);
                fseek(f, 0, SEEK_SET);
                char *buf = malloc(sz+1);
                if (buf) {
                    fread(buf,1,sz,f);
                    buf[sz] = '\0';
                    eval_chunk(buf);
                    free(buf);
                }
                fclose(f);
                did_something = 1;
            }
            // ignore script args
            break;
